import{_ as r,a0 as i,w as d,s as l,ao as a,I as p,x as t,a1 as n,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"安卓編年史（21）：安卓 4.2，果凍豆——全新 Nexus 設備，全新平板界面 | LCTT x X-CMD","titleTemplate":false,"description":"安卓編年史（21）：安卓 4.2，果凍豆——全新 Nexus 設備，全新平板界面 | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓編年史（21）：安卓 4.2，果凍豆——全新 Nexus 設備，全新平板界面 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓編年史（21）：安卓 4.2，果凍豆——全新 Nexus 設備，全新平板界面 | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/22 - The history of Android","title":"安卓編年史（21）：安卓 4.2，果凍豆——全新 Nexus 設備，全新平板界面","tag":"The history of Android","desc":""},"relativePath":"The history of Android/22 - The history of Android.md","filePath":"[post].md"}'),m={name:"The history of Android/22 - The history of Android.md"};function u(x,e,h,g,T,f){const o=i("Link");return d(),l("div",null,[e[20]||(e[20]=a('<h1 id="安卓編年史-21-安卓-4-2-果凍豆——全新-nexus-設備-全新平板界面" tabindex="-1">安卓編年史（21）：安卓 4.2，果凍豆——全新 Nexus 設備，全新平板界面 <a class="header-anchor" href="#安卓編年史-21-安卓-4-2-果凍豆——全新-nexus-設備-全新平板界面" aria-label="Permalink to “安卓編年史（21）：安卓 4.2，果凍豆——全新 Nexus 設備，全新平板界面”">​</a></h1><h3 id="安卓-4-2-果凍豆——全新-nexus-設備-全新平板界面" tabindex="-1">安卓 4.2，果凍豆——全新 Nexus 設備，全新平板界面 <a class="header-anchor" href="#安卓-4-2-果凍豆——全新-nexus-設備-全新平板界面" aria-label="Permalink to “安卓 4.2，果凍豆——全新 Nexus 設備，全新平板界面”">​</a></h3><p>安卓平台成熟的腳步越來越快，谷歌也將越來越多的應用託管到 Play 商店，需要通過系統更新來更新的應用越來越少。但是不間斷的更新還是要繼續的，2012 年 11 月，安卓 4.2 發佈。4.2 還是叫做“果凍豆”，這個版本主要是一些少量變動。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/unnamed.jpg" alt="LG 生產的 Nexus 4 和三星生產的 Nexus 10。"></p><p><em>LG 生產的 Nexus 4 和三星生產的 Nexus 10。 [Google/Ron Amadeo 供圖]</em></p><p>和安卓 4.2 一同發佈的還有兩部旗艦設備，Nexus 4 和 Nexus 10，都由谷歌直接在 Play 商店出售。Nexus 4 使用了 Nexus 7 的策略，令人驚訝的低價和高質量，並且無鎖設備售價 300 美元。Nexus 4 有一個 4 核 1.5GHz 驍龍 S4 Pro 處理器，2GB 內存以及 1280×768 分辨率 4.7 英寸 LCD 顯示屏。谷歌的新旗艦手機由 LG 生產，並和製造商一起將關注點轉向了材料和質量。Nexus 4 有着正反兩面雙面玻璃，這會讓你愛不釋手，它是有史以來觸感最佳的安卓手機之一。Nexus 4 最大的缺點是沒有 LTE 支持，那時候大部分手機，包括 Version Galaxy Nexus 都有更快的基帶。但 Nexus 4 的需求仍大大超出了谷歌的預料——發佈當日大量的流量拖垮了 Play 商店網站。手機在一小時之內銷售一空。</p>',6)),p("p",null,[e[1]||(e[1]=t("Nexus 10 是谷歌的第一部 10 英寸 Nexus 平板。該設備的亮點是 2560×1600 分辨率的顯示屏，在這個等級上是分辨率最高的。這背後是雙核 1.7GHz Cortex A15 處理器和 2GB 內存的強力支持。隨着時間一個月一個月地流逝，Nexus 10 似乎逐漸成為了第一部也是最後一部 10 英寸 Nexus 平板。通常這些設備每年都升級，但 Nexus 10 至今面世 16 個月了，可預見的未來還沒有新設備的跡象。谷歌在小尺寸的 7 英寸平板上做得很出色，它似乎更傾向於讓",-1)),n(o,{href:"http://arstechnica.com/gadgets/2014/01/hands-on-with-samsungs-notepro-and-tabpro-new-screen-sizes-and-magazine-ui/"},{default:s(()=>[...e[0]||(e[0]=[t("像三星",-1)])]),_:1}),e[2]||(e[2]=t("這樣的合作伙伴探索更大的平板家族。",-1))]),e[21]||(e[21]=a('<p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/JBvsjb.jpg" alt="新的鎖屏，壁紙，以及時鐘小部件設計。"></p><p><em>新的鎖屏，壁紙，以及時鐘小部件設計。 [Ron Amadeo 供圖]</em></p><p>4.2 為鎖屏帶來了很多變化。文字居中，並且對小時使用了較大的字重，對分鐘使用了較細的字體。鎖屏現在是分頁的，可以自定義小部件。鎖屏不僅僅是一個簡單的時鐘，用户還可以將其替換成其它小部件或者添加額外的頁面和更多的小部件。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/locksc2reen.jpg" alt="鎖屏的添加小部件頁面，小部件列表，鎖屏上的 Gmail 部件，以及滑動到相機。"></p><p><em>鎖屏的添加小部件頁面，小部件列表，鎖屏上的 Gmail 部件，以及滑動到相機。 [Ron Amadeo 供圖]</em></p><p>鎖屏現在就像是一個精簡版的主屏幕。頁面輪廓會顯示在鎖屏的左右兩側來提示用户可以滑動到有其他小部件的頁面。向左滑動頁面會顯示一箇中間帶有加號的簡單空白頁面，點擊加號會打開兼容鎖屏的小部件列表。鎖屏每個頁面限制一個小部件，將小部件向上或向下拖動可以展開或收起。最右側的頁面保留給了相機——一個簡單的滑動就能打開相機界面，但是你沒辦法滑動回來。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/42fix.png" alt="新的快速設置面板以及內置應用集合。"></p><p><em>新的快速設置面板以及內置應用集合。 [Ron Amadeo 供圖]</em></p><p>4.2 最大的新增特性之一就是“快速設置”面板。安卓 3.0 為平板引入了快速改變電源設置的途徑，4.2 終於將這種能力帶給了手機。通知中心右上角加入了一枚新圖標，可以在正常的通知列表和新的快速設置之間切換。快速設置提供了對屏幕亮度、網絡連接、電池以及數據用量更加快捷的訪問，而不用打開完整的設置界面。安卓 4.1 中頂部的設置按鈕移除掉了，快速設置中添加了一個按鈕來替代它。</p><p>應用抽屜和 4.2 中的應用陣容有很多改變。得益於 Nexus 4 更寬的屏幕橫縱比（5:3，Galaxy Nexus 是 16:9），應用抽屜可以顯示一行五個應用圖標的方陣。4.2 將自帶的瀏覽器替換為了 Google Chrome，自帶的日曆換成了 Google Calendar，它們都帶來了新的圖標設計。時鐘和相機應用在 4.2 中經過了重製，新的圖標也是其中的一部分。“Google Settings”是個新應用，用於提供對系統範圍內所有存在的谷歌賬户設置的快捷方式，它有着和 Google Search 和 Google+ 圖標一致的風格。谷歌地圖擁有了新圖標，谷歌縱橫，以往是谷歌地圖的一部分，作為對 Google+ location 的支持在這個版本退役。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/chroemcam.jpg" alt="瀏覽器替換為 Chrome，帶有全屏取景器的新相機界面。"></p><p><em>瀏覽器替換為 Chrome，帶有全屏取景器的新相機界面。 [Ron Amadeo 供圖]</em></p><p>原來的自帶瀏覽器在一段時間內對 Chrome 的模仿上下了不少功夫——它引入了許多 Chrome 的界面元素，許多 Chrome 的特性，甚至還使用了 Chrome 的 javascript 引擎——但安卓 4.2 來臨的時候，谷歌認為安卓版的 Chrome 已經準備好換下這個模仿者了。表面上看起來沒有多大不同；界面看起來不一樣，而且早期版本的 Chrome 安卓版滾動起來沒有原瀏覽器順暢。不過從深層次來説，一切都不一樣。安卓的主瀏覽器開發現在由 Google Chrome 團隊負責，而不是作為安卓團隊的子項目存在。安卓的默認瀏覽器從綁定安卓版本發佈、停滯不前的應用變成了不斷更新的 Play 商店應用。現在甚至還有一個每個月接收一些更新的 beta 通道。</p>',13)),p("p",null,[e[4]||(e[4]=t("相機界面經過了重新設計。它現在完全是個全屏應用，顯示攝像頭的實時圖像並且在上面顯示控制選項。佈局審美和安卓 1.5 的",-1)),n(o,{href:"http://cdn.arstechnica.net/wp-content/uploads/2013/12/device-2013-12-26-11016071.png"},{default:s(()=>[...e[3]||(e[3]=[t("相機設計",-1)])]),_:1}),e[5]||(e[5]=t("有很多共同之處：帶對焦的最小化的控制放置在取景器顯示之上。中間的控制環在你長按屏幕或點擊右下角圓形按鈕的時候顯示。你的手指保持在屏幕上時，你可以滑動來選擇環上的選項，通常是展開進入一個子菜單。在高亮的選項上釋放手指選中它。這靈感很明顯來自於安卓 4.0 瀏覽器中的快速控制，但是將選項安排在一個環上意味着你的手指幾乎總會擋住一部分界面。",-1))]),e[22]||(e[22]=a('<p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/clock-1.jpg" alt="時鐘應用，從一個只有兩個界面的應用變成功能強大，實用的應用。"></p><p><em>時鐘應用，從一個只有兩個界面的應用變成功能強大，實用的應用。 [Ron Amadeo 供圖]</em></p><p>時鐘應用經過了完整的改造，從一個簡單的兩個界面的鬧鐘，到一個世界時鐘、鬧鐘、定時器，以及秒錶俱全。時鐘應用的設計和谷歌之前引入的完全不同，有着極簡審美和紅色高亮。它看起來像是谷歌的一個試驗。甚至是幾個版本之後，這個設計語言似乎也僅限於這個應用。</p><p>時鐘的時間選擇器是經過特別精心設計的。它顯示一個簡單的數字盤，會智能地禁用會導致無效時間的數字。設置鬧鐘時間也不能在沒有明確選擇 AM 和 PM 時設置，永遠地解決了不小心將 9am 的鬧鐘設置成 9pm 的問題。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/tablet2.jpg" alt="平板的新系統界面使用了延展版的手機界面。"></p><p><em>平板的新系統界面使用了延展版的手機界面。 [Ron Amadeo 供圖]</em></p><p>安卓 4.2 中最有爭議的改變是平板界面，從單獨一個統一的底部系統欄變成帶有頂部狀態欄和底部系統欄的雙欄設計。新設計統一了手機和平板的界面，但批評人士説將手機界面延展到 10 英寸的橫向平板上是浪費空間。因為導航按鍵現在擁有了整個底欄，所以他們像手機界面那樣被居中。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/2014-03-06-14.55.png" alt="平板上的多用户，以及新的手勢鍵盤。"></p><p><em>平板上的多用户，以及新的手勢鍵盤。 [Ron Amadeo 供圖]</em></p><p>在平板上，安卓 4.2 帶來了多用户支持。在設置裏，新增了“用户”部分，你可以在這裏管理一台設備上的用户。設置在每個用户賬户內完成，安卓會給每個用户保存單獨的設置，主屏幕，應用以及應用數據。</p><p>4.2 還添加了有滑動輸入能力的鍵盤。用户可以將手指一直保持在屏幕上，按順序在字母按鍵上滑動來輸入，而不用像以前那樣一個一個字母單獨地輸入。</p><hr><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/05/r.amadeo-45843.jpg" alt="Ron Amadeo"></p>',13)),p("p",null,[n(o,{href:"http://arstechnica.com/author/ronamadeo"},{default:s(()=>[...e[6]||(e[6]=[t("Ron Amadeo",-1)])]),_:1}),e[8]||(e[8]=t(" / Ron是Ars Technica的評論編緝，專注於安卓系統和谷歌產品。他總是在追尋新鮮事物，還喜歡拆解事物看看它們到底是怎麼運作的。",-1)),n(o,{href:"https://twitter.com/RonAmadeo"},{default:s(()=>[...e[7]||(e[7]=[t("@RonAmadeo",-1)])]),_:1})]),e[23]||(e[23]=p("hr",null,null,-1)),p("p",null,[e[10]||(e[10]=t("via: ",-1)),n(o,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/22/"},{default:s(()=>[...e[9]||(e[9]=[t("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/22/",-1)])]),_:1})]),p("p",null,[e[13]||(e[13]=t("譯者：",-1)),n(o,{href:"https://github.com/alim0x"},{default:s(()=>[...e[11]||(e[11]=[t("alim0x",-1)])]),_:1}),e[14]||(e[14]=t(" 校對：",-1)),n(o,{href:"https://github.com/wxy"},{default:s(()=>[...e[12]||(e[12]=[t("wxy",-1)])]),_:1})]),p("p",null,[e[17]||(e[17]=t("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[15]||(e[15]=[t("LCTT",-1)])]),_:1}),e[18]||(e[18]=t(" 原創翻譯，",-1)),n(o,{href:"http://linux.cn/"},{default:s(()=>[...e[16]||(e[16]=[t("Linux中國",-1)])]),_:1}),e[19]||(e[19]=t(" 榮譽推出",-1))])])}const y=r(m,[["render",u]]);export{C as __pageData,y as default};
